"""Retention for completed checkpoints generated by a managed training run."""
from pathlib import Path
import re

from common import read_json, write_json


def retain_recent_checkpoints(run, completed_epoch):
    run = Path(run).resolve()
    metadata = read_json(run / "run.json")
    keep = metadata.get("keep_last_checkpoints")
    if keep is None:
        return []  # Older runs have no explicit retention policy.
    if type(keep) is not int or keep < 1 or not metadata.get("run_id"):
        raise ValueError("Invalid managed-run checkpoint retention policy")
    directory = run / "checkpoints"
    if directory.is_symlink() or not directory.is_dir():
        return []
    newest = directory / f"checkpoint_epoch_{completed_epoch:05d}.pyth"
    if newest.is_symlink() or not newest.is_file() or newest.stat().st_size == 0:
        return []  # Never remove an older restart point before the new save completed.
    candidates = []
    for path in directory.iterdir():
        match = re.fullmatch(r"checkpoint_epoch_(\d{5})\.pyth", path.name)
        if match and not path.is_symlink() and path.is_file() and path.stat().st_size > 0:
            epoch = int(match.group(1))
            if 0 < epoch <= completed_epoch:
                candidates.append((epoch, path))
    candidates.sort(reverse=True)
    removed = []
    for _, path in candidates[keep:]:
        size = path.stat().st_size
        path.unlink()
        removed.append(dict(name=path.name, bytes=size))
    write_json(run / "checkpoint_retention.json", dict(keep_last=keep, completed_epoch=completed_epoch,
               retained=[path.name for _, path in candidates[:keep]], removed_this_pass=removed,
               best_model="best.pyth is retained separately"))
    return removed
